# Serena is the MCP toolkit that gives coding agents IDE-level, symbol-aware
# retrieval and editing: it drives a language server per project and exposes the
# result as MCP tools. The formula installs the Python application; `uv` is a
# runtime dependency because SolidLSP launches per-language servers that are not
# Python packages (pyright is the default for Python) from on-demand uvx
# environments, cached under ~/.solidlsp and uv's data directory.
#
# The version is the Git tag of oraios/serena. The dependency set is generated by
# scripts/bump/serena.py from the release's own uv.lock rather than resolved
# fresh, so the formula installs the versions upstream tests and the exact
# security pins in pyproject.toml. `brew update-python-resources` is not used
# for that block; do not hand-edit between the markers.
class Serena < Formula
  include Language::Python::Virtualenv

  desc "Semantic code retrieval and editing toolkit for coding agents over MCP"
  homepage "https://github.com/oraios/serena"
  url "https://github.com/oraios/serena.git",
      tag:      "v2.1.0",
      revision: "5e4f5cd173c7ff3eed37ee3f1de6c266b937c5dc"
  license "GPL-3.0-or-later"
  head "https://github.com/oraios/serena.git", branch: "main"

  livecheck do
    url :homepage
    strategy :github_latest
  end

  depends_on arch: :arm64
  # The pyyaml sdist has no CPython 3.14 wheel, so pip builds it; Homebrew's
  # audit expects the libyaml it may link against to be declared.
  depends_on "libyaml"
  depends_on "python@3.14"
  depends_on "uv"

  # The wheels keep @rpath-relative dylib IDs (jiter, for example). Homebrew's
  # default relocation rewrites those to absolute paths, which fails inside the
  # wheels' fixed Mach-O header padding; unblob needs the same exception.
  preserve_rpath

  # The formula URL is a Git tag, so name the PyPI distribution explicitly for
  # Homebrew's Python tooling (`brew update-python-resources`, `brew audit`).
  pypi_packages package_name: "serena-agent"

  # BEGIN GENERATED PYPI RESOURCES (scripts/bump/serena.py)
