  # END GENERATED PYPI RESOURCES

  def install
    virtualenv_create(libexec, "python3.14")
    python = libexec/"bin/python"

    # Stage every fetched PyPI artifact under its original filename. Homebrew's
    # `pip_install` is not used: it passes `--no-binary=:all:`, which pip also
    # applies to build isolation, so hatchling (the app's build backend) and the
    # build backends of the two sdists would be forced to build themselves from
    # source and fail. Installing with pip's defaults lets those build backends
    # come from wheels while the runtime wheels stay wheels.
    staging = buildpath/"pypi"
    staging.mkpath
    resources.each do |resource|
      download = resource.cached_download
      odie "#{resource.name}: PyPI download is not in the cache" unless download.exist?

      filename = download.basename.to_s.sub(/\A\h{64}--/, "")
      staging.install download => filename
    end
    system python, "-m", "pip", "install", "--no-deps", "--no-compile", *staging.children

    system python, "-m", "pip", "install", "--no-deps", "--no-compile", buildpath

    # Link only the application's own console scripts; the dependency wheels
    # ship their own (flask, pyright, ...) and must not land on PATH.
    %w[serena serena-agent serena-hooks].each { |command| bin.install_symlink libexec/"bin"/command }
  end

  def caveats
    <<~EOS
      Initialise Serena once, then register it with the MCP client you use:

        serena init
        serena setup <client>     # or configure the client by hand

      A client that is configured by hand launches the server with:

        #{opt_bin}/serena start-mcp-server --context <client>

      Language servers are not bundled. `uv` is installed for them: pyright, the
      default Python language server, runs through `uvx` on first use, which also
      downloads the Python 3.13 interpreter uv pins for it. Other languages need
      their own toolchain (node/npm for TypeScript, a JDK for Java, ...), and uv
      and SolidLSP cache what they download under ~/.solidlsp and uv's data
      directory. Set SERENA_HOME to keep Serena's own configuration elsewhere.

      The optional dashboard uses pywebview and pystray, which are installed
      with the other Python dependencies.
    EOS
  end

  test do
    assert_match "Serena #{version}", shell_output("#{bin}/serena --version")
    assert_match "start-mcp-server", shell_output("#{bin}/serena --help")

    ENV["SERENA_HOME"] = (testpath/"home").to_s
    system libexec/"bin/python", "-c", <<~PY
      from serena.config.serena_config import SerenaConfig
      from serena.language_backend import BuiltinLanguageBackend
      SerenaConfig.init(builtin_language_backend=BuiltinLanguageBackend.LSP)
    PY
    assert_path_exists testpath/"home/serena_config.yml"
  end
end
